pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL, LogFile} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, uint256 depositAmount) public {
        amount = bound(amount, 1, 100 ether);
        depositAmount = bound(depositAmount, amount, 200 ether);
        address actor = address(0xBEEF);
        vm.deal(actor, depositAmount);

        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(actor);
        uint256 totalBefore = balBefore;

        vm.prank(actor);
        c.Collect(amount);

        uint256 actorBal = c.balances(actor);
        uint256 contractEth = address(c).balance;

        assertTrue(actorBal <= contractEth, "balance should not exceed contract ETH");
    }
}
